/* 离线报价计算，不读取或修改源文件。 */
(function(root){
'use strict';
const fields=['quote_date','supplier','item','spec','unit','units_per_pack','price','currency','delivery_days'];
function csv(text){
 text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],v='',quoted=false,closed=false;
 for(let i=0;i<text.length;i++){const c=text[i];
  if(quoted){if(c==='"'){if(text[i+1]==='"'){v+='"';i++;}else{quoted=false;closed=true;}}else v+=c;continue;}
  if(c==='"'){if(v||closed)throw Error('引号位置错误');quoted=true;}
  else if(c===','||c==='\n'||c==='\r'){row.push(v);v='';closed=false;if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(x=>x.trim()))rows.push(row);row=[];}}
  else{if(closed)throw Error('结束引号后有多余字符');v+=c;}
 }
 if(quoted)throw Error('引号未闭合');row.push(v);if(row.some(x=>x.trim()))rows.push(row);return rows;
}
function parse(text,source){
 const rows=csv(text);if(!rows.length)throw Error('文件为空');const header=rows.shift().map(x=>x.trim());
 if(new Set(header).size!==header.length)throw Error('列名重复');for(const f of fields)if(!header.includes(f))throw Error('缺少列 '+f);
 if(!rows.length)throw Error('没有报价行');
 return rows.map((r,i)=>{try{
  if(r.length!==header.length)throw Error('列数不一致');const q={source,line:i+2};for(const f of fields)q[f]=r[header.indexOf(f)].trim();
  for(const f of fields)if(!q[f])throw Error(f+' 为空');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(q.quote_date)||!Number.isFinite(Date.parse(q.quote_date))||new Date(q.quote_date).toISOString().slice(0,10)!==q.quote_date)throw Error('日期无效');
  for(const f of ['units_per_pack','price','delivery_days']){if(!/^\d+(\.\d+)?$/.test(q[f]))throw Error(f+' 必须为数字');q[f]=Number(q[f]);if(!Number.isFinite(q[f]))throw Error(f+' 无效');}
  if(q.price<=0||q.units_per_pack<=0||!Number.isInteger(q.units_per_pack)||!Number.isInteger(q.delivery_days))throw Error('价格、包装数量须为正数，数量及交期须为整数');
  if(!['piece','pack','box'].includes(q.unit))throw Error('unit 仅支持 piece / pack / box');
  if(q.unit==='piece'&&q.units_per_pack!==1)throw Error('piece 的 units_per_pack 必须为 1');
  if(q.currency!=='CNY')throw Error('只支持 CNY，不能混用币种');
  q.unitPrice=q.price/q.units_per_pack;return q;
 }catch(e){throw Error('第 '+(i+2)+' 行：'+e.message);}});
}
const key=q=>JSON.stringify([q.supplier,q.item,q.spec]);
const signature=q=>JSON.stringify(fields.map(f=>q[f]));
function compare(records){
 const by=new Map();for(const q of records){const k=key(q);if(!by.has(k))by.set(k,[]);by.get(k).push(q);}
 const groups=new Map();let superseded=0;
 for(const list of by.values()){
  const date=list.reduce((a,q)=>q.quote_date>a?q.quote_date:a,'');const latest=list.filter(q=>q.quote_date===date);superseded+=list.length-latest.length;
  const distinct=[...new Map(latest.map(q=>[signature(q),q])).values()];const q=distinct[0];const k=JSON.stringify([q.item,q.spec]);
  if(!groups.has(k))groups.set(k,{item:q.item,spec:q.spec,offers:[],conflicts:[]});
  if(distinct.length>1)groups.get(k).conflicts.push({supplier:q.supplier,date,rows:distinct});else groups.get(k).offers.push({...q,sources:latest.map(x=>x.source+':'+x.line)});
 }
 for(const g of groups.values())g.offers.sort((a,b)=>a.unitPrice-b.unitPrice||a.supplier.localeCompare(b.supplier));
 return {groups:[...groups.values()].sort((a,b)=>a.item.localeCompare(b.item)||a.spec.localeCompare(b.spec)),superseded};
}
const api={csv,parse,compare,signature};if(typeof module!=='undefined')module.exports=api;root.Quotes=api;
})(typeof globalThis!=='undefined'?globalThis:this);

