$script:root = $PSScriptRoot
$script:path = Join-Path $script:root '借还记录.json'
$script:assets = @(Import-Csv -LiteralPath (Join-Path $script:root 'inputs/assets.csv') -Encoding UTF8)
$names = @{A01='投影仪';A02='三脚架';A03='麦克风';A04='音箱';A05='延长线';A06='相机';A07='白板';A08='计时器'}
function Available($id) {
    $a = $script:assets | Where-Object asset_id -EQ $id
    if (!$a) { throw '找不到该器材。' }
    $used = 0
    foreach ($r in $script:records) { if ($r.asset_id -eq $id -and !$r.returned -and !$r.cancelled) { $used += [int]$r.quantity } }
    return ([int]$a.total_quantity - $used)
}
function Save-Records {
    $json = ConvertTo-Json -InputObject @($script:records) -Depth 5
    $temp = $script:path + '.tmp'
    [IO.File]::WriteAllText($temp, $json, (New-Object Text.UTF8Encoding($false)))
    if (Test-Path -LiteralPath $script:path) { [IO.File]::Replace($temp, $script:path, ($script:path + '.bak')) }
    else { [IO.File]::Move($temp, $script:path) }
}
function Commit($next) {
    $old = $script:records
    $script:records = @($next)
    try { Save-Records } catch { $script:records = $old; throw }
}
function Borrow($person, $id, $quantity, $time, $note) {
    if ([string]::IsNullOrWhiteSpace($person)) { throw '请填写借用人。' }
    if ($quantity -lt 1 -or $quantity -gt (Available $id)) { throw '数量必须大于零且不能超过可借数量。' }
    if ($time -gt (Get-Date).AddMinutes(1)) { throw '借出时间不能在未来。' }
    $r = [pscustomobject]@{id=[guid]::NewGuid().ToString();person=$person.Trim();asset_id=$id;quantity=[int]$quantity;borrowed=$time.ToString('o');returned='';cancelled='';note=$note.Trim()}
    Commit (@($script:records) + @($r))
}
function Change-Record($id, $action) {
    $copy = @((ConvertFrom-Json (ConvertTo-Json -InputObject @($script:records) -Depth 5)) | ForEach-Object { $_ })
    $r = $copy | Where-Object id -EQ $id
    if (!$r -or $r.returned -or $r.cancelled) { throw '请选择尚未归还、未作废的登记。' }
    if ($action -eq 'return') { $r.returned = (Get-Date).ToString('o') }
    else { $r.cancelled = (Get-Date).ToString('o') }
