    if (!$raw.Trim().StartsWith('[')) { throw '记录文件格式异常。' }
    $script:records = @((ConvertFrom-Json $raw) | ForEach-Object { $_ })
    $ids = @{}
    foreach ($r in $script:records) {
        if (!$r.id -or $ids.ContainsKey($r.id) -or !$r.person -or $r.quantity -lt 1 -or !($script:assets.asset_id -contains $r.asset_id)) { throw '记录文件包含无效登记。' }
        $ids[$r.id] = $true
        $null = [datetime]::Parse($r.borrowed)
        if ($r.returned) { $null = [datetime]::Parse($r.returned) }
    }
    foreach ($a in $script:assets) { if ((Available $a.asset_id) -lt 0) { throw '记录中的借出数量超过总库存。' } }
}
if ($SelfTest) {
    $script:path = Join-Path $script:root ('check-' + [guid]::NewGuid() + '.json')
    try {
        Load-Records
        if ((Available 'A06') -ne 1) { throw '初始库存失败' }
