const input = name => fs.readFileSync(path.join(root, 'inputs', name), 'utf8');
const rows = ['09-30.csv', '10-07.csv'].flatMap(name => api.parse(input(name), name));
const find = (result, item, spec) => result.find(g => g.item === item && g.spec === spec);
const first = api.groups(rows), paper = find(first, 'Paper', 'A4-80gsm'), pen = find(first, 'Pen', 'Black-0.5mm');
assert.equal(paper.offers[0].supplier, 'South'); assert.equal(paper.offers[0].base, 0.05);
assert.equal(pen.offers[0].supplier, 'South'); assert.equal(pen.offers[0].base, 1.4);
assert.equal(first.length, 3); assert.equal(paper.offers[0].source, '10-07.csv');
const header = input('10-07.csv').split('\n')[0];
const next = header + '\n2026-10-14,North,Paper,A4-80gsm,pack,500,40,CNY,3\n2026-10-14,South,Paper,A4-80gsm,pack,500,35,CNY,2\n2026-10-14,West,Paper,A4-80gsm,piece,1,0.065,CNY,1\n';
const updated = api.groups([...rows, ...api.parse(next, '10-14.csv')]);
assert.equal(find(updated, 'Paper', 'A4-80gsm').offers[0].supplier, 'West');
assert.equal(find(updated, 'Paper', 'A4-80gsm').offers[0].base, 0.065);
const conflict = header + '\n2026-10-07,South,Paper,A4-80gsm,pack,500,24,CNY,2\n';
const ambiguous = find(api.groups([...rows, ...api.parse(conflict, 'conflict.csv')]), 'Paper', 'A4-80gsm');
assert(ambiguous.conflicts.flat().some(c => c.supplier === 'South'));
assert(!ambiguous.offers.some(c => c.supplier === 'South'));
const backup = JSON.stringify({version:1,rows});
const restored = api.restore(backup);
assert.equal(restored.length, 9); assert.deepEqual(api.groups(restored), first);
assert.equal(api.merge(restored, restored).added, 0);
console.log(JSON.stringify({passed:true, initialPaper:paper.offers[0], initialPen:pen.offers[0],
  nextWeekPaper:find(updated,'Paper','A4-80gsm').offers[0], conflictExcluded:true, backupRoundTrip:true,
